(()=>{'use strict';const input=document.querySelector('[data-game-discovery-search]'),grid=document.querySelector('[data-game-discovery-results]'),count=document.querySelector('[data-game-discovery-count]');if(!input)return;const original=grid.innerHTML,originalCount=count.textContent,pages=document.querySelector('.game-pages');let games;const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));async function update(){const query=input.value.trim().toLowerCase();if(!query){grid.innerHTML=original;count.textContent=originalCount;pages.hidden=false;return;}try{games||=fetch('/data/game-discovery.json').then(r=>{if(!r.ok)throw Error();return r.json();});const all=await games;if(input.value.trim().toLowerCase()!==query)return;const results=all.filter(g=>(g.name+' '+g.series+' '+g.genre).toLowerCase().includes(query));count.textContent=results.length+' matches'+(results.length>48?' · showing first 48; refine the search':'');pages.hidden=true;grid.innerHTML=results.slice(0,48).map(g=>'<article class="game-discovery-card"><img src="'+esc(g.art)+'" alt="'+esc(g.name)+' game artwork" width="460" height="215" loading="lazy"><div><h2>'+esc(g.name)+'</h2><p>'+esc(g.genre)+'</p><a class="button secondary" href="/performance/?game='+encodeURIComponent(g.id)+'">Check performance coverage</a>'+(g.official?'<a class="game-original" href="'+esc(g.official)+'" target="_blank" rel="noopener">Official game listing</a>':'')+'</div></article>').join('')||'<p>No matches. Try a game title or series.</p>';}catch{count.textContent='Search is unavailable. Browse the page links instead.';}}input.addEventListener('input',update);})();
